revoke all privileges on table public.newsletter_subscribers from anon, authenticated;
drop policy if exists "Authors create own stories" on public.stories;
create policy "Authors create own draft stories" on public.stories for insert to authenticated with check (auth.uid() = author_id and status = 'draft');
drop policy if exists "Authors update own stories" on public.stories;
create policy "Authors update own drafts" on public.stories for update to authenticated using (auth.uid() = author_id and status = 'draft') with check (auth.uid() = author_id and status = 'draft');
drop policy if exists "Read own admin requests" on public.admin_requests;
create policy "Read own admin requests" on public.admin_requests for select to authenticated using (auth.uid() = requester_id);
drop policy if exists "Submit own pending admin request" on public.admin_requests;
create policy "Submit own pending admin request" on public.admin_requests for insert to authenticated with check (auth.uid() = requester_id and status = 'pending' and reviewed_by is null and reviewed_at is null);
drop policy if exists "Users read own roles" on public.app_roles;
create policy "Users read own roles" on public.app_roles for select to authenticated using (auth.uid() = user_id);
drop policy if exists "Create own bookmarks" on public.bookmarks;
create policy "Create own bookmarks" on public.bookmarks for insert to authenticated with check (auth.uid() = user_id);
drop policy if exists "Delete own bookmarks" on public.bookmarks;
create policy "Delete own bookmarks" on public.bookmarks for delete to authenticated using (auth.uid() = user_id);
drop policy if exists "Read own bookmarks" on public.bookmarks;
create policy "Read own bookmarks" on public.bookmarks for select to authenticated using (auth.uid() = user_id);
drop policy if exists "Follow as self" on public.follows;
create policy "Follow as self" on public.follows for insert to authenticated with check (auth.uid() = follower_id);
drop policy if exists "Unfollow as self" on public.follows;
create policy "Unfollow as self" on public.follows for delete to authenticated using (auth.uid() = follower_id);
drop policy if exists "Like as self" on public.story_likes;
create policy "Like as self" on public.story_likes for insert to authenticated with check (auth.uid() = user_id);
drop policy if exists "Remove own like" on public.story_likes;
create policy "Remove own like" on public.story_likes for delete to authenticated using (auth.uid() = user_id);
drop policy if exists "Comment as self on published story" on public.comments;
create policy "Comment as self on published story" on public.comments for insert to authenticated with check (auth.uid() = author_id and exists (select 1 from public.stories s where s.id = story_id and s.status = 'published'));
drop policy if exists "Delete own comments" on public.comments;
create policy "Delete own comments" on public.comments for delete to authenticated using (auth.uid() = author_id);
drop policy if exists "Profiles are readable" on public.profiles;
create policy "Profiles are readable" on public.profiles for select to anon, authenticated using (true);
drop policy if exists "Users update own profile" on public.profiles;
create policy "Users update own profile" on public.profiles for update to authenticated using (auth.uid() = id) with check (auth.uid() = id);